From 4ddb3050c04ec24ae84bbeceb6c8723c493bf9e9 Mon Sep 17 00:00:00 2001
From: Wesley Pettit <wppttt@amazon.com>
Date: Sun, 19 Jan 2020 23:06:06 -0800
Subject: [PATCH] http_client: add content-length header after body is set
 (#1895)

fixes a bug I committed in fcf15a9

Signed-off-by: Wesley Pettit <wppttt@amazon.com>

diff --git a/src/flb_http_client.c b/src/flb_http_client.c
index 4799d740e..26c12bc26 100644
--- a/src/flb_http_client.c
+++ b/src/flb_http_client.c
@@ -567,8 +567,6 @@ struct flb_http_client *flb_http_client(struct flb_upstream_conn *u_conn,
     c->flags       = flags;
     mk_list_init(&c->headers);

-    add_host_and_content_length(c);
-
     /* Check if we have a query string */
     p = strchr(uri, '?');
     if (p) {
@@ -593,6 +591,8 @@ struct flb_http_client *flb_http_client(struct flb_upstream_conn *u_conn,
         c->body_len = body_len;
     }

+    add_host_and_content_length(c);
+
     /* Check proxy data */
     if (proxy) {
         ret = proxy_parse(proxy, c);
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the `Content-Length` header being set before the body length was determined, leading to an incorrect value being sent in the HTTP request. This could result in issues with how the server interprets the request, potentially causing errors or unexpected behavior.

        Commit message:
        http_client: add content-length header after body is set
 (#1895)

fixes a bug I committed in fcf15a9

Signed-off-by: Wesley Pettit <wppttt@amazon.com>  

        Patch:

 struct flb_http_client *flb_http_client(struct flb_upstream_conn *u_conn,
                                         int method, const char *uri,
                                         const char *body, size_t body_len,
                                         const char *host, int port,
                                         const char *proxy, int flags)
 {
     int ret;
     char *p;
     char *buf = NULL;
     char *str_method = NULL;
     char *fmt_plain =                           \
         "%s %s HTTP/1.%i\r\n";
     char *fmt_proxy =                           \
         "%s http://%s:%i/%s HTTP/1.%i\r\n"
         "Proxy-Connection: KeepAlive\r\n";

     struct flb_http_client *c;

     switch (method) {
     case FLB_HTTP_GET:
         str_method = "GET";
         break;
     case FLB_HTTP_POST:
         str_method = "POST";
         break;
     case FLB_HTTP_PUT:
         str_method = "PUT";
         break;
     case FLB_HTTP_HEAD:
         str_method = "HEAD";
         break;
     };

     buf = flb_calloc(1, FLB_HTTP_BUF_SIZE);
     if (!buf) {
         flb_errno();
         return NULL;
     }

     /* FIXME: handler for HTTPS proxy */
     if (!proxy) {
         ret = snprintf(buf, FLB_HTTP_BUF_SIZE,
                        fmt_plain,
                        str_method,
                        uri,
                        flags & FLB_HTTP_10 ? 0 : 1,
                        body_len);
     }
     else {
         ret = snprintf(buf, FLB_HTTP_BUF_SIZE,
                        fmt_proxy,
                        str_method,
                        flags & FLB_HTTP_10 ? 0 : 1,
                        host,
                        port,
                        "",
                        body_len);
     }

     if (ret == -1) {
         flb_errno();
         flb_free(buf);
         return NULL;
     }

     c = flb_calloc(1, sizeof(struct flb_http_client));
     if (!c) {
         flb_free(buf);
         return NULL;
     }

     c->u_conn      = u_conn;
     c->method      = method;
     c->uri         = uri;
     c->host        = host;
     c->port        = port;
     c->header_buf  = buf;
     c->header_size = FLB_HTTP_BUF_SIZE;
     c->header_len  = ret;
     c->flags       = flags;
     mk_list_init(&c->headers);

-    add_host_and_content_length(c);
-
     /* Check if we have a query string */
     p = strchr(uri, '?');
     if (p) {
         p++;
         c->query_string = p;
     }

     /* Is Upstream connection using keepalive mode ? */
     if (u_conn->u->flags & FLB_IO_TCP_KA) {
         c->flags |= FLB_HTTP_KA;
     }

     /* Response */
     c->resp.content_length = -1;

     if ((flags & FLB_HTTP_10) == 0) {
         c->flags |= FLB_HTTP_11;
     }

     if (body && body_len > 0) {
         c->body_buf = body;
         c->body_len = body_len;
     }

+    add_host_and_content_length(c);
+
     /* Check proxy data */
     if (proxy) {
         ret = proxy_parse(proxy, c);
         if (ret != 0) {
             flb_free(buf);
             flb_free(c);
             return NULL;
         }
     }

     /* 'Read' buffer size */
     c->resp.data = flb_malloc(FLB_HTTP_DATA_SIZE_MAX);
     if (!c->resp.data) {
         flb_errno();
         flb_free(buf);
         flb_free(c);
         return NULL;
     }
     c->resp.data_len  = 0;
     c->resp.data_size = FLB_HTTP_DATA_SIZE_MAX;
     c->resp.data_size_max = FLB_HTTP_DATA_SIZE_MAX;

     return c;
 }



